48	+public class BookingService(AppDbContext dbContext)
49	+{
50	+    public async Task<CreateBookingResult> CreateBookingAsync(CreateBookingRequestDto request)
51	+    {
52	+        var invalidFields = new List<string>();
53	+        if (string.IsNullOrWhiteSpace(request.Name)) invalidFields.Add("name");
54	+        if (string.IsNullOrWhiteSpace(request.Email)) invalidFields.Add("email");
55	+        if (request.Seats is null || request.Seats.Count == 0) invalidFields.Add("seats");
56	+        if (invalidFields.Count > 0)
57	+        {
58	+            return CreateBookingResult.Invalid(invalidFields, "Pflichtangaben fehlen.");
59	+        }
60	+
61	+        var seatIds = request.Seats!.Select(s => s.SeatId).ToList();
62	+        if (seatIds.Distinct().Count() != seatIds.Count)
63	+        {
64	+            return CreateBookingResult.Invalid(["seats"], "Ein Sitzplatz wurde mehrfach angefragt.");
65	+        }
66	+
67	+        var room = await dbContext.Events
68	+            .Where(e => e.Id == request.EventId)
69	+            .Select(e => (Guid?)e.RoomId)
70	+            .FirstOrDefaultAsync();
71	+        if (room is null)
72	+        {
73	+            return CreateBookingResult.Invalid(["seats"], "Unbekannte Veranstaltung.");
74	+        }
75	+
76	+        var validSeatIds = await dbContext.Seats
77	+            .Where(s => s.RoomId == room.Value && seatIds.Contains(s.Id))
78	+            .Select(s => s.Id)
79	+            .ToListAsync();
80	+        var validCategoryIds = await dbContext.PriceCategories
81	+            .Where(pc => pc.EventId == request.EventId)
82	+            .Select(pc => pc.Id)
83	+            .ToListAsync();
84	+        var hasInvalidSeatOrCategory = request.Seats!.Any(s =>
85	+            !validSeatIds.Contains(s.SeatId) || !validCategoryIds.Contains(s.PriceCategoryId));
86	+        if (hasInvalidSeatOrCategory)
87	+        {
88	+            return CreateBookingResult.Invalid(["seats"], "Ein Sitzplatz oder eine Preiskategorie ist ungültig.");
89	+        }
90	+
91	+        // EF Core InMemory (Unit-Tests, AC7) unterstützt keine echten Transaktionen — nur bei
92	+        // relationalen Providern (SQL Server) wird eine echte Transaktion gestartet.
93	+        await using IDbContextTransaction? transaction = dbContext.Database.IsRelational()
94	+            ? await dbContext.Database.BeginTransactionAsync(System.Data.IsolationLevel.ReadCommitted)
95	+            : null;
96	+
97	+        // Schritt 1 (AD-1): aktive Konflikte lesen, BEVOR irgendetwas eingefügt wird.
98	+        var conflictingSeatIds = await dbContext.BookingSeats
99	+            .Where(bs => bs.EventId == request.EventId && bs.IsActive && seatIds.Contains(bs.SeatId))
100	+            .Select(bs => bs.SeatId)
101	+            .ToListAsync();
102	+
103	+        if (conflictingSeatIds.Count > 0)
104	+        {
105	+            if (transaction is not null) await transaction.RollbackAsync();
106	+            return CreateBookingResult.Conflict(await SeatLabelsAsync(conflictingSeatIds));
107	+        }
108	+
109	+        var reference = await GenerateUniqueReferenceAsync();
110	+        var booking = new Booking
111	+        {
112	+            Id = Guid.NewGuid(),
113	+            Reference = reference,
114	+            EventId = request.EventId,
115	+            Name = request.Name!.Trim(),
116	+            Email = request.Email!.Trim(),
117	+            Status = BookingStatus.Active
118	+        };
119	+        dbContext.Bookings.Add(booking);
120	+
121	+        foreach (var seat in request.Seats!)
122	+        {
123	+            dbContext.BookingSeats.Add(new BookingSeat
124	+            {
125	+                Id = Guid.NewGuid(),
126	+                BookingId = booking.Id,
127	+                EventId = request.EventId,
128	+                SeatId = seat.SeatId,
129	+                PriceCategoryId = seat.PriceCategoryId,
130	+                IsActive = true
131	+            });
132	+        }
133	+
134	+        try
135	+        {
136	+            // Schritt 2 (AD-1): Insert — der filtered unique index fängt eine echte Race
137	+            // zwischen Schritt 1 und 2 zweier gleichzeitiger Transaktionen ab.
138	+            await dbContext.SaveChangesAsync();
139	+            if (transaction is not null) await transaction.CommitAsync();
140	+        }
141	+        catch (DbUpdateException)
142	+        {
143	+            if (transaction is not null) await transaction.RollbackAsync();
144	+            dbContext.ChangeTracker.Clear();
145	+            var stillConflicting = await dbContext.BookingSeats
146	+                .Where(bs => bs.EventId == request.EventId && bs.IsActive && seatIds.Contains(bs.SeatId))
147	+                .Select(bs => bs.SeatId)
148	+                .ToListAsync();
149	+            return CreateBookingResult.Conflict(await SeatLabelsAsync(stillConflicting));
150	+        }
151	+
152	+        return CreateBookingResult.Success(await BuildBookingDtoAsync(booking.Id));
153	+    }
154	+
155	+    private async Task<List<string>> SeatLabelsAsync(List<Guid> seatIds) =>
156	+        await dbContext.Seats
157	+            .Where(s => seatIds.Contains(s.Id))
158	+            .Select(s => s.Row + s.Column.ToString())
159	+            .ToListAsync();
160	+
161	+    private async Task<string> GenerateUniqueReferenceAsync()
162	+    {
163	+        for (var attempt = 0; attempt < 5; attempt++)
164	+        {
165	+            var candidate = BookingReferenceGenerator.Generate();
166	+            if (!await dbContext.Bookings.AnyAsync(b => b.Reference == candidate))
167	+            {
168	+                return candidate;
169	+            }
170	+        }
171	+        throw new InvalidOperationException("Konnte keine eindeutige Buchungsreferenz erzeugen.");
172	+    }
173	+
174	+    private async Task<BookingDto> BuildBookingDtoAsync(Guid bookingId)
175	+    {
176	+        var booking = await dbContext.Bookings.SingleAsync(b => b.Id == bookingId);
177	+        var seats = await dbContext.BookingSeats
178	+            .Where(bs => bs.BookingId == bookingId)
179	+            .Join(dbContext.Seats, bs => bs.SeatId, s => s.Id, (bs, s) => new { bs, s })
180	+            .Join(dbContext.PriceCategories, x => x.bs.PriceCategoryId, pc => pc.Id, (x, pc) =>
181	+                new BookingSeatDto(x.s.Id, x.s.Row, x.s.Column, pc.Id, pc.Preis))
182	+            .ToListAsync();
183	+
184	+        var totalCents = seats.Sum(s => (long)Math.Round(s.Price * 100));
185	+        return new BookingDto(booking.Reference, booking.EventId, booking.Status.ToString(), seats, totalCents / 100m);
186	+    }
187	+}
