14	+    private const string Alphabet = "23456789ABCDEFGHJKMNPQRSTUVWXYZ";
15	+    // ceil(128 / log2(31)) = 26 Zeichen ⇒ ≥128 Bit Entropie (NFR-4, "Größenordnung UUID v4").
16	+    private const int Length = 26;
17	+
18	+    public static string Generate() => RandomNumberGenerator.GetString(Alphabet, Length);
