32	        {
33	            var venue = new Venue
34	            {
35	                Id = Guid.NewGuid(),
36	                Name = seedVenue.Name
37	            };
38	            venueIdMap[seedVenue.Id] = venue.Id;
39	            dbContext.Venues.Add(venue);
40	
41	            foreach (var seedRoom in seedVenue.Raeume)
42	            {
43	                var room = new Room
44	                {
45	                    Id = Guid.NewGuid(),
46	                    Name = seedRoom.Name,
47	                    VenueId = venue.Id,
48	                    Reihen = seedRoom.Reihen,
49	                    SpaltenAnzahl = seedRoom.Spalten,
50	                    GangSpalten = seedRoom.Gang?.Spalten ?? new List<int>()
51	                };
52	                roomIdMap[seedRoom.Id] = room.Id;
53	                dbContext.Rooms.Add(room);
54	
55	                for (var column = 1; column <= seedRoom.Spalten; column++)
56	                {
57	                    if (room.GangSpalten.Contains(column))
58	                    {
59	                        continue;
60	                    }
61	
62	                    foreach (var reihe in room.Reihen)
63	                    {
64	                        var seat = new Seat { Id = Guid.NewGuid(), RoomId = room.Id, Row = reihe, Column = column };
65	                        seatIdMap[(room.Id, reihe, column)] = seat.Id;
66	                        dbContext.Seats.Add(seat);
67	                    }
68	                }
69	            }
70	        }
71	
72	        var pendingSeedBookings = new List<(SeedVeranstaltung SeedEvent, Guid EventId, Guid FirstPriceCategoryId)>();
73	
74	        foreach (var seedEvent in datenbestand.Veranstaltungen)
75	        {
76	            var @event = new Event
77	            {
78	                Id = Guid.NewGuid(),
79	                Titel = seedEvent.Titel,
80	                Beschreibung = seedEvent.Beschreibung,
81	                DauerMinuten = seedEvent.DauerMinuten,
82	                Altersfreigabe = seedEvent.Altersfreigabe,
83	                Zeitpunkt = DateTime.SpecifyKind(seedEvent.Zeitpunkt, DateTimeKind.Unspecified),
84	                VenueId = venueIdMap[seedEvent.SpielstaetteId],
85	                RoomId = roomIdMap[seedEvent.RaumId]
86	            };
87	            dbContext.Events.Add(@event);
88	
89	            Guid? firstPriceCategoryId = null;
90	            for (var index = 0; index < seedEvent.Preiskategorien.Count; index++)
91	            {
92	                var seedPreiskategorie = seedEvent.Preiskategorien[index];
93	                var priceCategoryId = Guid.NewGuid();
94	                if (index == 0)
95	                {
96	                    firstPriceCategoryId = priceCategoryId;
97	                }
98	
99	                dbContext.PriceCategories.Add(new PriceCategory
100	                {
101	                    Id = priceCategoryId,
102	                    EventId = @event.Id,
103	                    Name = seedPreiskategorie.Name,
104	                    Preis = seedPreiskategorie.Preis,
105	                    Reihenfolge = index
106	                });
107	            }
108	
109	            if (seedEvent.Preiskategorien.Count > 0)
110	            {
111	                pendingSeedBookings.Add((seedEvent, @event.Id, firstPriceCategoryId!.Value));
112	            }
113	        }
114	
115	        await dbContext.SaveChangesAsync();
116	
117	        foreach (var (seedEvent, eventId, firstPriceCategoryId) in pendingSeedBookings)
118	        {
119	            if (seedEvent.BelegteSitzplaetze.Count == 0)
120	            {
121	                continue;
122	            }
123	
124	            var seats = seedEvent.BelegteSitzplaetze
125	                .Select(label => ParseSeatLabel(label))
126	                .Select(parsed => seatIdMap[(roomIdMap[seedEvent.RaumId], parsed.Row, parsed.Column)])
127	                .Select(seatId => new CreateBookingSeatRequestDto(seatId, firstPriceCategoryId))
128	                .ToList();
129	
130	            var result = await bookingService.CreateBookingAsync(new CreateBookingRequestDto(
131	                eventId, "Anfangsbestand", "anfangsbestand@import.lokal", seats));
132	
133	            if (result.Booking is null)
134	            {
135	                throw new InvalidOperationException(
136	                    $"Seed-Import: belegteSitzplaetze für Veranstaltung {seedEvent.Id} konnten nicht als Buchung angelegt werden ({result.ValidationDetail}).");
137	            }
138	        }
139	    }
