141	    private static (string Row, int Column) ParseSeatLabel(string label)
142	    {
143	        var match = Regex.Match(label, "^([A-Za-z]+)(\\d+)$");
144	        return (match.Groups[1].Value, int.Parse(match.Groups[2].Value));
145	    }
