318	      return;
319	    }
320	    this.activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
321	
322	    if (this.activePointers.size === 2 && this.pinchStartDistance !== null && this.pinchMidpoint !== null) {
323	      const [a, b] = Array.from(this.activePointers.values());
324	      const currentDistance = distance(a, b);
325	      this.zoom.set(clamp(this.pinchStartZoom * (currentDistance / this.pinchStartDistance), MIN_ZOOM, MAX_ZOOM));
326	
327	      const currentMidpoint = midpoint(a, b);
328	      this.panX.update((x) => x + (currentMidpoint.x - this.pinchMidpoint!.x));
329	      this.panY.update((y) => y + (currentMidpoint.y - this.pinchMidpoint!.y));
330	      this.pinchMidpoint = currentMidpoint;
331	    } else if (this.activePointers.size === 1 && event.buttons > 0 && this.lastPanPoint) {
332	      this.panX.update((x) => x + (event.clientX - this.lastPanPoint!.x));
333	      this.panY.update((y) => y + (event.clientY - this.lastPanPoint!.y));
334	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
335	    }
