208	          column: seat.column,
209	          categoryName: category?.name ?? null,
210	          price: category?.price ?? 0
211	        };
212	      })
213	      .sort((a, b) => a.row.localeCompare(b.row) || a.column - b.column);
214	  });
215	
216	  protected readonly totalPrice = computed<number>(() => {
217	    const totalCents = this.selectedSeatSummaries().reduce(
218	      (sum, seat) => sum + Math.round(seat.price * 100),
219	      0
220	    );
221	    return totalCents / 100;
222	  });
223	
224	  protected readonly soldOut = computed<boolean>(() => {
225	    const map = this.seatMap();
226	    return map !== null && map.seats.length > 0 && !map.seats.some((seat) => seat.status === 'Free');
227	  });
228	
229	  protected onGridKeydown(event: KeyboardEvent): void {
230	    if (event.key === 'Escape') {
231	      const seatId = this.panelSeatId();
232	      if (seatId) {
233	        event.preventDefault();
234	        this.panelDismissed.set(true);
235	        const seat = this.seatMap()?.seats.find((s) => s.seatId === seatId);
236	        if (seat) {
237	          this.seatComponents()
238	            .find((s) => s.row() === seat.row && s.column() === seat.column)
239	            ?.focusSeat();
240	        }
241	      }
242	      return;
243	    }
244	
245	    const map = this.seatMap();
246	    const current = map?.seats.find((s) => s.seatId === this.focusedSeatId());
247	    if (!map || !current) {
248	      return;
249	    }
250	
251	    const rowIndex = map.rows.indexOf(current.row);
252	    let nextSeat: SeatModel | undefined;
253	
254	    switch (event.key) {
255	      case 'ArrowRight':
256	        for (let c = current.column + 1; c <= map.columns && !nextSeat; c++) {
257	          nextSeat = this.selectableSeatAt(current.row, c);
258	        }
259	        break;
260	      case 'ArrowLeft':
261	        for (let c = current.column - 1; c >= 1 && !nextSeat; c--) {
262	          nextSeat = this.selectableSeatAt(current.row, c);
263	        }
264	        break;
265	      case 'ArrowDown':
266	        for (let r = rowIndex + 1; r < map.rows.length && !nextSeat; r++) {
267	          nextSeat = this.selectableSeatAt(map.rows[r], current.column);
268	        }
269	        break;
270	      case 'ArrowUp':
271	        for (let r = rowIndex - 1; r >= 0 && !nextSeat; r--) {
272	          nextSeat = this.selectableSeatAt(map.rows[r], current.column);
273	        }
274	        break;
275	      default:
276	        return;
277	    }
278	
279	    event.preventDefault();
280	    if (nextSeat) {
281	      this.setFocusedSeatId(nextSeat.seatId);
282	      this.seatComponents()
283	        .find((s) => s.row() === nextSeat!.row && s.column() === nextSeat!.column)
284	        ?.focusSeat();
285	    }
286	  }
287	
288	  private selectableSeatAt(row: string, column: number): SeatModel | undefined {
289	    const seat = this.seatByPosition().get(`${row}:${column}`);
290	    return seat?.status === 'Free' ? seat : undefined;
291	  }
292	
293	  protected onWheel(event: WheelEvent): void {
294	    event.preventDefault();
295	    if (event.deltaY === 0) {
296	      return;
297	    }
298	    const delta = event.deltaY > 0 ? -0.1 : 0.1;
299	    this.zoom.set(clamp(this.zoom() + delta, MIN_ZOOM, MAX_ZOOM));
300	  }
301	
302	  protected onPointerDown(event: PointerEvent): void {
303	    (event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId);
304	    this.activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
305	
306	    if (this.activePointers.size === 1) {
307	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
308	    } else if (this.activePointers.size === 2) {
309	      const [a, b] = Array.from(this.activePointers.values());
310	      this.pinchStartDistance = distance(a, b);
311	      this.pinchStartZoom = this.zoom();
312	      this.pinchMidpoint = midpoint(a, b);
313	    }
314	  }
315	
316	  protected onPointerMove(event: PointerEvent): void {
317	    if (!this.activePointers.has(event.pointerId)) {
318	      return;
319	    }
320	    this.activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
321	
322	    if (this.activePointers.size === 2 && this.pinchStartDistance !== null && this.pinchMidpoint !== null) {
323	      const [a, b] = Array.from(this.activePointers.values());
324	      const currentDistance = distance(a, b);
325	      this.zoom.set(clamp(this.pinchStartZoom * (currentDistance / this.pinchStartDistance), MIN_ZOOM, MAX_ZOOM));
326	
327	      const currentMidpoint = midpoint(a, b);
328	      this.panX.update((x) => x + (currentMidpoint.x - this.pinchMidpoint!.x));
329	      this.panY.update((y) => y + (currentMidpoint.y - this.pinchMidpoint!.y));
330	      this.pinchMidpoint = currentMidpoint;
331	    } else if (this.activePointers.size === 1 && event.buttons > 0 && this.lastPanPoint) {
332	      this.panX.update((x) => x + (event.clientX - this.lastPanPoint!.x));
333	      this.panY.update((y) => y + (event.clientY - this.lastPanPoint!.y));
334	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
335	    }
336	  }
337	
338	  protected onPointerUp(event: PointerEvent): void {
339	    (event.currentTarget as HTMLElement).releasePointerCapture?.(event.pointerId);
340	    this.activePointers.delete(event.pointerId);
341	
342	    if (this.activePointers.size < 2) {
343	      this.pinchStartDistance = null;
344	      this.pinchMidpoint = null;
345	    }
346	
347	    if (this.activePointers.size === 0) {
348	      this.lastPanPoint = null;
349	    } else {
350	      const [remaining] = Array.from(this.activePointers.values());
351	      this.lastPanPoint = remaining;
352	    }
353	  }
354	
355	  protected onSubmitBooking(): void {
356	    const errors = new Set<string>();
357	    if (!this.bookingName().trim()) errors.add('name');
358	    if (!this.bookingEmail().trim()) errors.add('email');
359	    const summaries = this.selectedSeatSummaries();
360	    if (summaries.length === 0 || summaries.some((s) => s.categoryName === null)) {
361	      errors.add('seats');
362	    }
363	    if (errors.size > 0) {
364	      this.fieldErrors.set(errors);
365	      return;
366	    }
367	
368	    this.fieldErrors.set(new Set());
369	    this.conflictMessage.set(null);
370	    this.submitting.set(true);
371	
372	    const map = this.seatMap();
373	    if (!map) return;
374	
375	    const request: CreateBookingRequest = {
376	      eventId: this.id(),
377	      name: this.bookingName().trim(),
378	      email: this.bookingEmail().trim(),
379	      seats: summaries.map((s) => ({
380	        seatId: s.seatId,
381	        priceCategoryId: this.assignedCategoryId().get(s.seatId)!
382	      }))
383	    };
384	
385	    this.bookingService.createBooking(request).subscribe({
386	      next: (booking) => {
387	        this.router.navigate(['/buchungen', booking.reference], { state: { booking } });
388	      },
389	      error: (err: HttpErrorResponse) => {
390	        this.submitting.set(false);
391	        if (err.status === 409) {
392	          const problem = err.error as ConflictProblemDetails;
393	          const labels = problem.conflictingSeats ?? [];
394	          this.conflictMessage.set(
395	            labels.length === 1
396	              ? `Platz ${labels[0]} ist inzwischen vergeben.`
397	              : `Plätze ${labels.join(', ')} sind inzwischen vergeben.`
398	          );
399	          this.reloadSeatMapAfterConflict(labels);
400	        } else if (err.status === 400) {
401	          const problem = err.error as ValidationProblemDetails;
402	          this.fieldErrors.set(new Set(Object.keys(problem.errors ?? {})));
403	        }
404	      }
405	    });
406	  }
407	
408	  private reloadSeatMapAfterConflict(conflictingLabels: string[]): void {
409	    this.seatMapService.getSeatMap(this.id()).subscribe((seatMap) => {
410	      this.seatMap.set(seatMap);
411	      const conflictingSeatIds = new Set(
412	        seatMap.seats.filter((s) => conflictingLabels.includes(s.row + s.column)).map((s) => s.seatId)
413	      );
414	      this.selectedSeatIds.update((current) => new Set([...current].filter((id) => !conflictingSeatIds.has(id))));
415	      this.assignedCategoryId.update((current) => {
416	        const next = new Map(current);
417	        for (const id of conflictingSeatIds) next.delete(id);
418	        return next;
419	      });
420	    });
421	  }
422	}

