    fixture.detectChanges();
    (compiled.querySelectorAll('.price-category-panel__pill')[0] as HTMLElement).click();
    fixture.detectChanges();

    (seatEls[1].querySelector('.seat') as HTMLElement).click();
    fixture.detectChanges();
    (compiled.querySelectorAll('.price-category-panel__pill')[0] as HTMLElement).click();
