    }
    if (errors.size > 0) {
      this.fieldErrors.set(errors);
      return;
    }

    this.fieldErrors.set(new Set());
    this.conflictMessage.set(null);
    this.submitting.set(true);

    const map = this.seatMap();
    if (!map) return;

